import * as D from './domain.js';
import { Store, api } from './store.js';
import { holidays } from './holidays.js';
const $=s=>document.querySelector(s), app=$('#app'),dialog=$('#dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attrs=o=>Object.entries(o).filter(([,v])=>v!==null&&v!==undefined&&v!==false).map(([k,v])=>`${k}="${esc(v===true?'':v)}"`).join(' ');
const button=(label,action='',extra={},cls='')=>`<button ${attrs({'data-action':action,...extra,class:cls||null})}>${label}</button>`;
const blank=(text='还没有记录',action='')=>`<div class="empty"><span class="empty-icon">◌</span>${esc(text)}${action}</div>`;
const badge=(s,c='')=>`<span class="badge ${c}">${esc(s)}</span>`;
const money=n=>hidden?'••••':D.money(n);
const formatDate=n=>new Date(n).toLocaleDateString('zh-CN',{month:'short',day:'numeric'});
const titleOf=n=>n.body.split('\n').find(x=>x.trim())?.replace(/^#+\s*/,'')||'无标题';
const views={overview:['◈','资产总览','把每一份积累，看得清清楚楚。'],bills:['≋','账单','生活的收支，一笔一笔记下来。'],todos:['✓','待办','把心里的事，放在这里。'],diary:['▤','日记','记下今天，也留给以后的自己。'],notes:['▧','笔记','让零散的想法，慢慢长成知识。'],week:['◷','周复盘','停下来，看看这一周走过的路。'],health:['♡','健康','身体的变化，值得认真记录。'],food:['♧','饮食','记下吃了什么，不必追求完美。'],countdowns:['◴','倒数日','给期待的日子，留一个位置。'],settings:['⚙','设置','你的数据，由你掌握。']};
let store=null,user=null,page='overview',selectedDate=D.today(),query='',todoView='today',noteTopic='',billMonth=D.today().slice(0,7),selected=new Set(),editor=null,saveTimer=null,maxTimer=null,savePromise=Promise.resolve(),modalSave=null,toastTimer,hidden=localStorage.getItem('gain-hidden')==='1';
let theme=localStorage.getItem('gain-theme')||'system';
function applyTheme(){document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):theme;}
applyTheme();matchMedia('(prefers-color-scheme:dark)').addEventListener('change',applyTheme);
function notify(text,undo){clearTimeout(toastTimer);$('#toast').innerHTML=`<span>${esc(text)}</span>${undo?button('撤销','undo'):''}`;$('#toast').classList.add('visible');if(undo)$('#toast button').onclick=()=>{undo().catch(fail);$('#toast').classList.remove('visible');};toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?6000:4500);}
function fail(e){notify(e.message||String(e));}
const data=()=>store.data;
const live=k=>D.live(data()[k]);
const nameOf=id=>data().accounts.find(a=>a.id===id)?.name||'外部';
const groupOf=a=>data().groups.find(g=>g.id===a.groupId);
function download(text,name,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function mutate(fn,message='已保存',undo=false){let before;await store.change(d=>{before=structuredClone(d);fn(d);});const generation=store.state.generation;if(message)notify(message,undo?async()=>{await store.change((d,state)=>{D.ensure(state.generation===generation,'数据已发生新变化，请在回收站恢复记录');for(const k of Object.keys(d))delete d[k];Object.assign(d,before);});}:null);}
function formField(key,label,value='',type='text',options=null,extra={}) {
  if(type==='checkbox')return `<label class="field checkbox"><input ${attrs({type,name:key,checked:!!value,...extra})}>${esc(label)}</label>`;
  let input;
  if(type==='select')input=`<select name="${esc(key)}">${options.map(([v,n])=>`<option ${attrs({value:v,selected:String(value??'')===String(v)})}>${esc(n)}</option>`).join('')}</select>`;
  else if(type==='textarea')input=`<textarea ${attrs({name:key,...extra})}>${esc(value)}</textarea>`;
  else input=`<input ${attrs({type,name:key,value:value??'',...extra})}>`;
  return `<label class="field ${type==='textarea'?'full':''}"><span>${esc(label)}</span>${input}</label>`;
}
function openForm(title,fields,save,footer='') {
  modalSave=save;const formGeneration=store.state.generation;dialog.innerHTML=`<form id="modal-form"><div class="dialog-head"><h2>${esc(title)}</h2>${button('✕','close-dialog',{'aria-label':'关闭'},'ghost')}</div><div class="form-grid">${fields}</div>${footer}<div class="form-error" role="alert"></div><div class="dialog-actions">${button('取消','close-dialog')}<button class="primary" type="submit">保存</button></div></form>`;
  dialog.querySelectorAll('button[data-action]').forEach(b=>b.type='button');dialog.showModal();
  $('#modal-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;const form=new FormData(e.target);const v=Object.fromEntries(form);e.target.querySelectorAll('input[type=checkbox]').forEach(x=>{v[x.name]=x.checked;});b.disabled=true;try{store.expectedGeneration=formGeneration;await modalSave(v);dialog.close();if(!$('#toast').classList.contains('visible'))notify('已保存');}catch(e){dialog.querySelector('.form-error').textContent=e.message;}finally{if(store)store.expectedGeneration=null;b.disabled=false;}};
}
async function confirmAction(title,description,action){openForm(title,`<p class="subtitle full">${esc(description)}</p>`,action);$('#modal-form button[type=submit]').textContent='确认';}
function card(title,content,action=''){return `<section class="card"><div class="card-head"><h2>${esc(title)}</h2>${action}</div>${content}</section>`;}
function chart(points,{format=money}={}) {
  if(!points.length)return blank('记录后，这里会出现变化曲线');
  const max=Math.max(...points.map(p=>p.value)),min=Math.min(...points.map(p=>p.value)),span=max-min||1;
  const coords=points.map((p,i)=>`${points.length===1?300:15+i/(points.length-1)*570},${145-(p.value-min)/span*120}`);
  const path=coords.join(' ');
  return `<svg class="chart" viewBox="0 0 600 165" role="img" aria-label="${esc(`趋势，${points.length} 个记录点，最低 ${format(min)}，最高 ${format(max)}`)}" preserveAspectRatio="none"><path class="gridline" d="M0 25H600 M0 85H600 M0 145H600"/><polygon class="area" points="${coords[0].split(',')[0]},160 ${path} ${coords.at(-1).split(',')[0]},160"/><polyline class="line" points="${path}"/>${coords.map((p,i)=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="3" fill="currentColor"><title>${esc(points[i].label||formatDate(points[i].at))}：${esc(format(points[i].value))}</title></circle>`).join('')}</svg><div class="chart-labels"><span>${esc(points[0].label||formatDate(points[0].at))}</span><span>${esc(format(max))}</span><span>${esc(points.at(-1).label||formatDate(points.at(-1).at))}</span></div><details class="chart-table"><summary>查看数据</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>数值</th></tr></thead><tbody>${points.map(p=>`<tr><td>${esc(p.label||new Date(p.at).toLocaleString('zh-CN'))}</td><td>${esc(format(p.value))}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function login(message='') {
  app.innerHTML=`<main class="login"><section class="login-story"><div class="brand"><img src="/icon.svg" alt=""><div>日盈<small>GAIN · EVERY DAY</small></div></div><div><div class="eyebrow">YOUR LIFE, GROWING.</div><h1>日日行动，<br>日日有盈。</h1><p>把资产、计划和生活的点滴，<br>收进一个安静的地方。</p></div><small>每一份积累，都有它的意义。</small></section><section class="login-panel"><form class="login-form" id="login-form"><div class="eyebrow">WELCOME BACK</div><h2>回到你的日盈</h2><p class="subtitle">使用手机端账号登录，继续你的记录。</p><br>${formField('username','账号','','text',null,{autocomplete:'username',required:true,maxlength:32})}${formField('password','密码','','password',null,{autocomplete:'current-password',required:true,maxlength:256})}<p id="login-error" class="form-error" role="alert">${esc(message)}</p><button class="primary" type="submit">登录日盈 →</button><p class="footnote">账号由你自己的日盈服务管理员创建。<br>与手机共用数据，实时同步；网页只把数据放在页面内存里。</p></form></section></main>`;
  $('#login-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;$('#login-error').textContent='';try{const v=Object.fromEntries(new FormData(e.target));const {value}=await api('/login',{method:'POST',body:JSON.stringify(v)});e.target.reset();await start(value.user);}catch(e){$('#login-error').textContent=e.status===401?'账号或密码不正确':e.message;btn.disabled=false;}};
}
async function start(u){store?.close();user=u;store=new Store(u);await store.load();store.addEventListener('change',()=>{if(editor)updateStatus();else render();});render();store.startPolling(20000);try{await store.sync();}catch(e){store.fail(e);}render();}
function status(){return store.busy?'同步中…':store.error?'未同步 · 将自动重试':store.state.dirty?'有改动待同步':'已与云端同步';}
function render(){
  if(!store)return;
  const [icon,title,subtitle]=views[page];
  app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/icon.svg" alt="日盈"><div>日盈<small>GAIN · EVERY DAY</small></div></div><nav class="nav" aria-label="主导航">${Object.entries(views).map(([k,[icon,label]],i)=>`${i===2?'<div class="nav-separator"></div>':''}${button(`<span class="nav-icon">${icon}</span>${label}`,'navigate',{'data-page':k,'aria-current':page===k?'page':null},page===k?'active':'')}`).join('')}</nav><div class="sidebar-bottom"><span class="avatar">${esc(user.username.slice(0,1).toUpperCase())}</span>${esc(user.username)}<br><br>日日行动，日日有盈。</div></aside><main class="main"><header class="topbar"><span>${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}</span><div class="actions"><span id="sync-status"><i class="dot"></i>${esc(status())}</span>${button('↻ 同步','sync',{},'small ghost')}</div></header><div id="sync-banner">${syncBanner()}</div><div class="page-head"><div><div class="eyebrow">GAIN / ${page.toUpperCase()}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${pageActions()}</div></div><div id="page-content">${pageContent()}</div></main></div>`;
  bindPage();
}
function syncBanner(){if(store.error)return `<div class="banner error">${esc(store.error)} ${button('重试同步','sync',{},'small')}${button('重新登录','relogin',{},'small')}</div>`;if(store.state.dirty)return `<div class="banner">正在把改动保存到云端…</div>`;return '';}
function updateStatus(){if($('#sync-status'))$('#sync-status').textContent=status();if($('#sync-banner'))$('#sync-banner').innerHTML=syncBanner();if($('.editor-status'))$('.editor-status').textContent=editor?.pending?'正在保存…':editor?.conflict?'内容冲突：当前文字已另存为草稿':store.error?'已保存在页面内，尚未上云':'已保存到云端';}
function pageActions(){switch(page){case 'overview':return button('＋ 记一笔','flow',{},'')+button('盘点资产','stocktake',{},'primary');case 'bills':return button('＋ 记一笔','flow',{},'primary');case 'todos':return button('清单管理','lists')+button('＋ 新待办','todo',{},'primary');case 'notes':return button('主题管理','topics')+button('＋ 新笔记','new-note',{},'primary');case 'health':return button('健康档案','health-profile')+button('＋ 记录体重','measurement',{},'primary');case 'food':return button('＋ 记录饮食','food-edit',{},'primary');case 'countdowns':return button('＋ 新倒数日','countdown',{},'primary');case 'diary':return button('那年今日','memories')+button('写今天','today',{},'primary');default:return '';}}
function pageContent(){return ({overview:overview,bills:bills,todos:todos,diary:diary,notes:notes,week:week,health:health,food:food,countdowns:countdowns,settings:settings})[page]();}
function overview(){
  const d=data(),t=D.totals(d),points=D.trend(d),goal=d.netWorthGoal;
  if(!d.groups.length)return `<div class="grid"><section class="card hero"><div class="empty large"><span class="empty-icon">◈</span><h2>开始记录你的资产</h2><p class="subtitle">网页数据与手机端账号同步，随时接着写。</p>${button('开始使用','seed-groups',{},'primary')}<p class="footnote">会建好现金、储蓄、虚拟、负债、投资 5 个空分组，账户由你自己添加。</p></div></section></div>`;
  const accountRows=D.sorted(d.groups).map(g=>{const accounts=D.sorted(d.accounts.filter(a=>a.groupId===g.id&&!a.isDisabled));return `<details open><summary class="group-head"><span><span class="color-dot g${(g.colorIndex%8)+1}"></span>${esc(g.name)} · ${accounts.length}</span><span>¥ ${money(accounts.reduce((n,a)=>n+(D.balance(d,a.id)??0),0))}</span></summary>${accounts.map(a=>`<div class="row"><span class="account-icon">${a.kind==='INVESTMENT'?'↗':g.isLiability?'▱':'▰'}</span><button class="text-button grow" data-action="account-detail" data-id="${esc(a.id)}"><strong>${esc(a.name)}</strong><small>${esc(a.institution||a.purpose||(a.kind==='INVESTMENT'?'投资账户':'现金账户'))}${a.lockedUntil&&a.lockedUntil>Date.now()?' · 锁定中':''}${a.includeInTotal?'':' · 不计入净资产'}</small></button><button class="text-button amount" data-action="valuation" data-id="${esc(a.id)}">${money(g.isLiability?Math.abs(D.balance(d,a.id)??0):D.balance(d,a.id))}</button></div>`).join('')||blank('这个分组还没有账户')}</details>`;}).join('');
  return `<div class="grid overview"><div class="stack"><section class="card hero"><div class="metric-row"><span class="eyebrow">MY NET WORTH / 净资产</span>${button(hidden?'显示金额':'隐藏金额','privacy',{},'small')}</div><div class="big-number"><span class="currency">¥</span>${money(t.netWorth)}</div><small>${points.length?`最近盘点 · ${formatDate(points.at(-1).at)}`:'从第一笔资产开始，记录你的积累'}</small><div class="hero-bottom"><div><small>总资产</small><strong>¥ ${money(t.assets)}</strong></div><div><small>总负债</small><strong>¥ ${money(Math.abs(t.liabilities))}</strong></div><div><small>负债率</small><strong>${t.assets?Math.round(Math.abs(t.liabilities)/t.assets*100):0}%</strong></div></div></section>${card('我的账户',accountRows||blank('添加第一个账户，开始资产记录'),button('分组','groups',{},'small ghost')+button('＋ 添加账户','account',{},'small'))}${card('净资产趋势',`<div class="toolbar">${['3','6','12','all'].map((v,i)=>button(['3 个月','半年','1 年','全部'][i],'trend-range',{'data-range':v},'small')).join('')}${button('盘点历史','snapshots',{},'small ghost')}</div><div id="trend-chart">${chart(points)}</div>`)}</div><div class="stack">${card('攒钱目标',goal?`<div class="metric">¥ ${money(goal)}</div><div class="progress"><progress value="${Math.max(0,t.netWorth)}" max="${goal}"></progress></div><div class="metric-row"><small>已完成 ${Math.max(0,Math.min(100,t.netWorth/goal*100)).toFixed(1)}%</small><small>还差 ¥ ${money(Math.max(0,goal-t.netWorth))}</small></div>`:blank('给每一份努力，一个方向'),button(goal?'调整':'设定','goal',{},'small ghost'))}${card('可用现金',`<div class="metric">¥ ${money(t.cash)}</div><small>可随时动用的现金类资产</small><div class="row"><span class="grow muted">锁定资金</span><span>¥ ${money(t.locked)}</span></div><div class="row"><span class="grow muted">投资资产</span><span>¥ ${money(t.investment)}</span></div>`)}${card('今天的事',todoRows(live('todos').filter(t=>!t.completedAt&&!t.repeatEndedAt&&t.planDate&&t.planDate<=D.today()).slice(0,4)),button('全部 →','navigate',{'data-page':'todos'},'small ghost'))}${card('每日积累',habitView(D.today()))}${card('本月收支',billSummary(D.today().slice(0,7)))}</div></div>`;
}
const categories={food:'餐饮',shopping:'购物',transport:'交通',housing:'居住',health:'医疗',entertainment:'娱乐',education:'学习',salary:'工资',bonus:'奖金',gift:'人情',other:'其他'};
function billSummary(month){const rows=data().flows.filter(f=>new Date(f.at).getFullYear()+'-'+String(new Date(f.at).getMonth()+1).padStart(2,'0')===month);const expense=rows.filter(f=>f.kind==='EXPENSE').reduce((n,f)=>n+f.amount,0),income=rows.filter(f=>f.kind==='INCOME').reduce((n,f)=>n+f.amount,0);return `<div class="metric-row"><div><small>支出</small><div class="metric">${money(expense)}</div></div><div><small>收入</small><div class="metric">${money(income)}</div></div></div><small>本月结余 ¥ ${money(income-expense)}</small>`;}
function flowRows(rows){return rows.map(f=>`<div class="row"><span class="account-icon">${f.kind==='INCOME'?'↙':f.kind==='EXPENSE'?'↗':'⇄'}</span><button class="text-button grow" data-action="flow" data-id="${esc(f.id)}"><strong>${esc(f.note||categories[f.category]||D.flowKinds[f.kind])}</strong><small>${formatDate(f.at)} · ${esc(nameOf(f.fromAccountId))} → ${esc(nameOf(f.toAccountId))}${f.fee?` · 手续费 ${money(f.fee)}`:''}</small></button><span class="amount">${f.kind==='EXPENSE'?'−':f.kind==='INCOME'?'+':''}${money(f.amount)}</span>${button('删除','delete',{'data-table':'flows','data-id':f.id},'small ghost')}</div>`).join('')||blank('还没有流水，记下第一笔吧');}
function bills(){const rows=data().flows.filter(f=>['EXPENSE','INCOME'].includes(f.kind)&&D.dateString(new Date(f.at)).startsWith(billMonth)).sort((a,b)=>b.at-a.at);const sums={};rows.filter(f=>f.kind==='EXPENSE').forEach(f=>sums[f.category]=(sums[f.category]||0)+f.amount);const total=Object.values(sums).reduce((a,b)=>a+b,0);return `<div class="toolbar"><input aria-label="账单月份" type="month" id="bill-month" value="${billMonth}">${button('全部流水','all-flows',{},'small')}</div><div class="grid overview"><div class="stack">${card('本月账单',billSummary(billMonth))}${card('收支明细',flowRows(rows))}</div>${card('支出分类',Object.entries(sums).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="row"><div class="grow"><strong>${esc(categories[k]||'其他')}</strong><small>${(v/total*100).toFixed(1)}%</small></div><span>${money(v)}</span></div>`).join('')||blank('本月还没有支出'))}</div>`;}
function habitView(date){const d=data(),habits=(d.habits.length?d.habits:D.defaultHabits).filter(h=>(!h.addedOn||h.addedOn<=date)&&(!h.removedOn||h.removedOn>date)||d.habitChecks.some(c=>c.date===date&&c.habit===h.key));return `<div class="habits">${D.sorted(habits).map((h,i)=>{const c=d.habitChecks.find(c=>c.date===date&&c.habit===h.key);return button(`<span>${c?.skipped?'−':c?'✓':['✦','↗','♧','◉','☾'][i%5]}</span>${esc(h.label)}`,'habit',{'data-key':h.key,'data-date':date,title:h.rubric||h.label,'aria-pressed':!!c},`habit ${c&&!c.skipped?'checked':''}`);}).join('')}</div>`;}
function todoRows(rows){return D.sorted(rows).map(t=>`<div class="todo-item"><div class="row" draggable="true" data-drag-table="todos" data-id="${esc(t.id)}"><input aria-label="选择 ${esc(t.title)}" type="checkbox" data-select="${esc(t.id)}" ${selected.has(t.id)?'checked':''}><button class="todo-check ${t.completedAt?'done':''}" data-action="complete" data-id="${esc(t.id)}" aria-label="${t.completedAt?'撤销完成':'完成'} ${esc(t.title)}">${t.completedAt?'✓':''}</button><button class="text-button grow" data-action="todo" data-id="${esc(t.id)}"><strong class="${t.completedAt?'done-text':''}">${esc(t.title)}</strong><small>${t.important?badge('重要','warm'):''}${t.planDate?badge(t.planDate<tD()&&!t.completedAt?'已逾期 · '+t.planDate:t.planDate,t.planDate<tD()?'error':''):''}${t.remindTime?esc(t.remindTime):''}${t.kind==='REPEAT_SOURCE'?badge('重复'):''}${t.deadline?` 截止 ${esc(t.deadline)}`:''}</small></button>${button('删除','delete',{'data-table':'todos','data-id':t.id},'small ghost')}</div>${data().checklistItems.some(c=>c.todoId===t.id)?`<div class="checklist">${D.sorted(data().checklistItems.filter(c=>c.todoId===t.id)).map(c=>`<label class="row"><input type="checkbox" data-check="${esc(c.id)}" ${c.done?'checked':''}><span class="${c.done?'done-text':''}">${esc(c.text)}</span></label>`).join('')}</div>`:''}</div>`).join('')||blank('这里已经清空了，留一点时间给自己。');}
const tD=()=>D.today();
function todos(){const d=data();let rows=live('todos');if(todoView==='log')rows=rows.filter(t=>t.completedAt);else {rows=rows.filter(t=>!t.completedAt&&!t.repeatEndedAt&&!d.todoLists.some(l=>l.id===t.listId&&(l.archivedAt||l.deletedAt)));if(todoView==='today')rows=rows.filter(t=>t.planDate&&t.planDate<=D.today());if(todoView==='inbox')rows=rows.filter(t=>!t.planDate&&!t.someday&&!t.listId);if(todoView==='planned')rows=rows.filter(t=>t.planDate&&t.planDate>D.today());if(todoView==='someday')rows=rows.filter(t=>t.someday);if(todoView.startsWith('list:'))rows=rows.filter(t=>t.listId===todoView.slice(5));}rows=rows.filter(t=>(t.title+' '+t.notes).toLowerCase().includes(query.toLowerCase()));return `<div class="tabs">${Object.entries({today:'今天',inbox:'收件箱',planned:'计划',someday:'以后再说',all:'全部',log:'日志'}).map(([k,n])=>button(n,'todo-view',{'data-view':k},todoView===k?'active':'')).join('')}</div><div class="toolbar"><input type="search" id="search" placeholder="搜索待办与备注" value="${esc(query)}" aria-label="搜索待办"><select id="list-filter" aria-label="清单"><option value="">我的清单</option>${live('todoLists').filter(l=>!l.archivedAt).map(l=>`<option value="${esc(l.id)}" ${todoView==='list:'+l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select>${button('导出日历','calendar',{},'small')}${button('每日习惯','habits',{},'small')}</div>${selected.size?`<div class="selection">已选 ${selected.size} 项 ${button('完成','batch-complete',{},'small')}${button('改期 / 移动','batch-move',{},'small')}${button('合成检查清单','batch-nest',{},'small')}${button('删除','batch-delete',{},'small')}${button('取消选择','clear-selection',{},'small')}</div>`:''}<div class="grid overview"><section class="card">${todoRows(rows)}</section><div class="stack">${card('每日积累',habitView(D.today()))}${card('温柔提醒',`<p class="subtitle">拖动条目可以排序，也可以多选后批量整理。<br><br>网页打开时可发送浏览器通知。关闭页面后的准时提醒，请继续使用手机版。</p>${button('启用浏览器通知','notifications',{},'small')}`)}</div></div>`;}
function notes(){let rows=live('notes').filter(n=>(!noteTopic||n.topicId===noteTopic)&&n.body.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||a.position-b.position);const review=[...live('notes')].filter(n=>!n.pinned&&D.dateString(new Date(Math.max(n.updatedAt,n.reviewedAt??0)))<D.today()).sort((a,b)=>Math.max(a.updatedAt,a.reviewedAt??0)-Math.max(b.updatedAt,b.reviewedAt??0))[0];return `<div class="toolbar"><input type="search" id="search" placeholder="搜索笔记、内容或 #标签" value="${esc(query)}" aria-label="搜索笔记"><select id="topic-filter" aria-label="主题"><option value="">所有主题</option>${data().noteTopics.map(t=>`<option value="${esc(t.id)}" ${noteTopic===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><select id="note-sort" aria-label="排序"><option value="position">手动排序</option><option value="updatedAt">最近更新</option><option value="createdAt">最近创建</option></select></div>${review&&!query?`<div class="banner">今日回顾 · ${esc(titleOf(review))} ${button('重新读读','open-note',{'data-id':review.id},'small')}${button('今天略过','review-note',{'data-id':review.id},'small')}</div>`:''}<div class="note-grid" id="note-grid">${noteCards(rows)}</div>`;}
function noteCards(rows){return rows.map(n=>`<article class="card note" draggable="true" data-drag-table="notes" data-id="${esc(n.id)}"><div class="card-head"><button class="text-button" data-action="open-note" data-id="${esc(n.id)}"><h3>${n.pinned?'⌑ ':''}${esc(titleOf(n))}</h3></button>${button('⋯','note-options',{'data-id':n.id,'aria-label':'笔记操作'},'small ghost')}</div><button class="text-button grow" data-action="open-note" data-id="${esc(n.id)}"><p>${esc(n.body.split('\n').slice(1).join('\n').slice(0,200)||'继续写下你的想法…')}</p></button><footer><small>${esc(data().noteTopics.find(t=>t.id===n.topicId)?.name||'未归类')}</small><small>${formatDate(n.updatedAt)}</small></footer></article>`).join('')||blank('新建一篇笔记，让想法留下来。');}
function calendar(){const first=selectedDate.slice(0,7)+'-01',start=(D.day(first).getDay()+6)%7,last=new Date(D.day(first).getFullYear(),D.day(first).getMonth()+1,0).getDate();return `<div class="metric-row">${button('‹','calendar-month',{'data-direction':-1},'small ghost')}<strong>${esc(first.slice(0,7))}</strong>${button('›','calendar-month',{'data-direction':1},'small ghost')}</div><div class="calendar">${'一二三四五六日'.split('').map(x=>`<small>${x}</small>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:last},(_,i)=>{const date=first.slice(0,8)+String(i+1).padStart(2,'0');return button(String(i+1),'select-date',{'data-date':date},`${date===selectedDate?'active ':''}${live('diaryEntries').some(e=>e.date===date&&e.body)?'has-entry':''}`);}).join('')}</div>`;}
function diary(){const entry=live('diaryEntries').find(e=>e.date===selectedDate);let lunar='';try{lunar=new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{month:'long',day:'numeric'}).format(D.day(selectedDate));}catch{}return `<div class="editor-layout"><aside class="card editor-sidebar">${calendar()}<input type="search" id="search" aria-label="搜索日记" placeholder="搜索日记" value="${esc(query)}"><div class="entry-list">${live('diaryEntries').filter(e=>e.body.includes(query)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,40).map(e=>`<div class="row"><button class="text-button grow" data-action="select-date" data-date="${e.date}"><strong>${esc(e.date)}</strong><small>${esc(e.body.slice(0,30))}</small></button></div>`).join('')}</div></aside><section class="card"><div class="editor-meta"><input type="date" id="editor-date" value="${selectedDate}" aria-label="日记日期"><small>${esc(lunar)} ${esc(holidays[selectedDate]?.name||'')}${entry?.city?` · ${esc(entry.city)} ${entry.tempMin??''}–${entry.tempMax??''}℃`:''}</small><select id="mood" aria-label="心情"><option value="">今天的心情</option>${['😣 难受','😔 低落','🙂 平静','😊 开心','🥰 超开心'].map((m,i)=>`<option value="${i+1}" ${entry?.mood===i+1?'selected':''}>${m}</option>`).join('')}</select></div>${habitView(selectedDate)}<textarea class="editor-body" id="text-editor" aria-label="日记正文" placeholder="今天，有什么想记下的？">${esc(entry?.body||'')}</textarea><div class="editor-status">自动保存在本机</div><div class="toolbar">${button('提炼到笔记','extract',{},'small')}${button('本周复盘','open-week',{},'small')}${entry?button('删除这篇','delete',{'data-table':'diaryEntries','data-id':entry.id},'small ghost'):''}</div><details><summary class="muted">这一天完成的事</summary>${todoRows(live('todos').filter(t=>t.completedAt&&D.dateString(new Date(t.completedAt))===selectedDate))}</details></section></div>`;}
function week(){const start=D.monday(selectedDate),end=D.addDays(start,6),entries=live('diaryEntries').filter(e=>e.date>=start&&e.date<=end),review=live('weeklyReviews').find(r=>r.weekStart===start),done=live('todos').filter(t=>t.completedAt&&D.dateString(new Date(t.completedAt))>=start&&D.dateString(new Date(t.completedAt))<=end),checks=data().habitChecks.filter(h=>h.date>=start&&h.date<=end&&!h.skipped),weights=data().bodyMeasurements.filter(m=>m.date>=start&&m.date<=end),previous=data().bodyMeasurements.filter(m=>m.date>=D.addDays(start,-7)&&m.date<start),avg=a=>a.reduce((n,m)=>n+m.weightG,0)/a.length;return `<div class="toolbar">${button('← 上周','week-step',{'data-direction':-7},'small')}<input id="editor-date" type="date" value="${start}" aria-label="选择一周">${button('下周 →','week-step',{'data-direction':7},'small')}<small>${start} — ${end}</small></div><div class="grid three">${card('写下的日子',`<div class="metric">${entries.filter(e=>e.body).length}<small> / 7 天</small></div>`)}${card('完成与积累',`<div class="metric">${done.length}<small> 项待办 · ${checks.length} 次打卡</small></div>`)}${card('身体的变化',`<div class="metric">${weights.length&&previous.length?((avg(weights)-avg(previous))/1000).toFixed(2):'—'}<small> kg · 周均变化</small></div>`)}</div><br><div class="grid overview"><section class="card"><h2>这一周，我想说</h2><textarea id="text-editor" class="editor-body" aria-label="周复盘正文" placeholder="哪些事做得不错？下周想做些什么？">${esc(review?.body||'')}</textarea><div class="editor-status">自动保存在本机</div><div class="toolbar">${button('提炼到笔记','extract',{},'small')}${review?button('删除复盘','delete',{'data-table':'weeklyReviews','data-id':review.id},'small ghost'):''}</div></section><div class="stack">${card('七天的片段',entries.map(e=>`<div class="row"><button class="text-button grow" data-action="select-date" data-date="${e.date}"><strong>${e.date}</strong><p class="prose">${esc(e.body.slice(0,180))}</p></button></div>`).join('')||blank('本周还没有日记'))}${card('从这一周提炼',data().noteSources.filter(s=>s.kind==='WEEK'&&s.ref===start||s.kind==='DAY'&&s.ref>=start&&s.ref<=end).map(s=>data().notes.find(n=>n.id===s.noteId&&!n.deletedAt)).filter(Boolean).map(n=>button(esc(titleOf(n)),'open-note',{'data-id':n.id},'small')).join('')||blank('提炼日记，让收获留下来'))}</div></div>`;}
function health(){const rows=[...data().bodyMeasurements].sort((a,b)=>a.date.localeCompare(b.date)),latest=rows.at(-1),p=data().healthProfile,bmi=latest&&p?latest.weightG/1000/(p.heightMm/1000)**2:null,seven=rows.filter(m=>m.date>=D.addDays(D.today(),-6)&&m.date<=D.today());return `<div class="grid three">${card('最近体重',`<div class="metric">${latest?(latest.weightG/1000).toFixed(2):'—'}<small> kg</small></div><small>${latest?.date||'开始记录身体的变化'}</small>`)}${card('BMI',`<div class="metric">${bmi?.toFixed(1)||'—'}</div><small>${p?'根据健康档案中的身高计算':'填写健康档案后显示'}</small>`)}${card('7 天平均',`<div class="metric">${seven.length?(seven.reduce((n,m)=>n+m.weightG,0)/seven.length/1000).toFixed(2):'—'}<small> kg</small></div><small>只计算实际称重的日子</small>`)}</div><br><div class="grid overview"><div class="stack">${card('体重趋势',chart(rows.map(m=>({label:m.date,value:m.weightG/1000})),{format:n=>n.toFixed(2)+' kg'}))}${card('体脂率趋势',chart(rows.filter(m=>m.bodyFatBp!=null).map(m=>({label:m.date,value:m.bodyFatBp/100})),{format:n=>n.toFixed(1)+'%'}))}</div>${card('称重记录',[...rows].reverse().map(m=>`<div class="row"><button class="grow text-button" data-action="measurement" data-id="${m.id}"><strong>${m.date}</strong><small>${m.bodyFatBp!=null?'体脂 '+m.bodyFatBp/100+'%':''} ${esc(m.note||'')}</small></button><span>${m.weightG/1000} kg</span>${button('删除','delete',{'data-table':'bodyMeasurements','data-id':m.id},'small ghost')}</div>`).join('')||blank('记录一次称重，从今天开始'))}</div>`;}
function food(){const entries=data().foodEntries.filter(f=>f.date===selectedDate).sort((a,b)=>a.eatenAt-b.eatenAt),total=entries.reduce((n,f)=>n+D.energy(f),0),p=data().healthProfile,w=[...data().bodyMeasurements].filter(m=>m.date<=selectedDate).sort((a,b)=>b.date.localeCompare(a.date))[0];let burn=null;if(p&&w){const date=D.day(selectedDate),birth=D.day(p.birthDate),age=date.getFullYear()-birth.getFullYear()-(selectedDate.slice(5)<p.birthDate.slice(5)?1:0);if(age>=18)burn=10*w.weightG+625*p.heightMm-5000*age+(p.sex==='MALE'?5000:-161000);}return `<div class="toolbar"><input type="date" id="food-date" aria-label="饮食日期" value="${selectedDate}">${button('最近吃过','recent-food',{},'small')}</div><div class="grid three">${card('今日摄入',`<div class="metric">${Math.round(total/1000)}<small> kcal</small></div>`)}${card('估算基础代谢',`<div class="metric">${burn?Math.round(burn/1000):'—'}<small> kcal</small></div>`)}${card('静息缺口',`<div class="metric">${burn?Math.round((burn-total)/1000):'—'}<small> kcal</small></div>`)}</div><br>${card('吃过的食物',entries.map(f=>`<div class="row"><span class="account-icon">♧</span><button class="grow text-button" data-action="food-edit" data-id="${f.id}"><strong>${esc(f.name||'一次饮食记录')}</strong><small>${f.per?`${f.amount} ${f.unit==='SERVING'?'半份':f.unit==='G'?'g':'ml'} · `:''}${new Date(f.eatenAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}${f.proteinMg!=null?` · 蛋白质 ${((f.per?f.proteinMg*f.amount/f.per:f.proteinMg)/1000).toFixed(1)} g`:''}</small></button><span>${Math.round(D.energy(f)/1000)} kcal</span>${button('删除','delete',{'data-table':'foodEntries','data-id':f.id},'small ghost')}</div>`).join('')||blank('估个大概，也是一份有用的记录'))}<br>${card('近七天摄入',chart(Array.from({length:7},(_,i)=>D.addDays(selectedDate,i-6)).filter(date=>data().foodEntries.some(f=>f.date===date)).map(date=>({label:date,value:data().foodEntries.filter(f=>f.date===date).reduce((n,f)=>n+D.energy(f),0)/1000})),{format:n=>Math.round(n)+' kcal'}))}<p class="footnote">基础代谢按手机版的计算规则估算，只作记录展示；没有记录的日子不会被当作零摄入。</p>`;}
function countdowns(){return `<div class="note-grid">${data().countdowns.map(c=>{let target=D.day(c.date),now=D.day(D.today());if(c.yearly){const m=target.getMonth(),date=target.getDate(),y=now.getFullYear();target=new Date(y,m,Math.min(date,new Date(y,m+1,0).getDate()),12);if(target<now)target=new Date(y+1,m,Math.min(date,new Date(y+1,m+1,0).getDate()),12);}const days=Math.round((target-now)/86400000);return `<section class="card"><div class="card-head"><h3>${c.pinned?'⌑ ':''}${esc(c.title)}</h3>${button('编辑','countdown',{'data-id':c.id},'small ghost')}</div><div class="metric">${Math.abs(days)}<small> 天${days<0?'前':'后'}</small></div><small>${esc(c.date)}${c.yearly?' · 每年重复':''}</small><div class="dialog-actions">${button('删除','delete',{'data-table':'countdowns','data-id':c.id},'small ghost')}</div></section>`;}).join('')||blank('记下下一个值得期待的日子。')}</div>`;}
function settings(){return `<div class="grid"><div class="stack">${card('账号与同步',`<div class="row"><span class="avatar">${esc(user.username[0].toUpperCase())}</span><div class="grow"><strong>${esc(user.username)}</strong><small>与手机共用的日盈账号</small></div>${button('退出登录','logout',{},'small')}</div><div class="row"><span class="grow">${esc(status())}</span>${button('立即同步','sync',{},'small primary')}</div><div class="row"><span class="grow">云端版本 ${store.state.revision}</span>${button('历史版本','revisions',{},'small')}</div><div class="row"><span class="grow">账号安全</span>${button('修改密码','password',{},'small')}</div><p class="footnote">网页不把数据保存在浏览器：刷新、关闭标签页后重新从云端读取。未上云的改动会随页面关闭而丢失，状态栏显示「已与云端同步」才算保存完成。</p>`)}${card('数据与备份',`<div class="row"><span class="grow">兼容手机版的 JSON 备份</span>${button('导出备份','export',{},'small')}</div><div class="row"><span class="grow">从手机备份恢复</span>${button('导入备份','import',{},'small')}</div><div class="row"><span class="grow">本次打开期间导入前的数据</span>${button('下载副本','previous',{},'small')}</div><div class="row"><span class="grow">已删除的内容</span>${button('回收站','trash',{},'small')}</div><div class="row"><span class="grow">未解决的文字草稿</span>${button('查看草稿','drafts',{},'small')}</div>`)}${card('账户管理',button('分组管理','groups',{},'small')+' '+button('已停用账户','disabled-accounts',{},'small'))}</div><div class="stack">${card('外观',`<label class="field"><span>主题</span><select id="theme">${[['system','跟随系统'],['light','浅色'],['dark','深色']].map(([v,n])=>`<option value="${v}" ${theme===v?'selected':''}>${n}</option>`).join('')}</select></label>${button(hidden?'显示资产金额':'隐藏资产金额','privacy',{},'small')}`)}${card('网页提醒与日历',`<p class="subtitle">浏览器通知需要页面保持打开。系统休眠或关闭网页后，仍请用手机接收提醒。</p><br>${button('启用通知','notifications',{},'small')} ${button('导出待办日历','calendar',{},'small')}<p class="footnote">日历文件可导入系统日历。相同待办使用固定标识，导入是否更新现有事件由日历应用决定。</p>`)}${card('关于日盈 Web',`<p class="subtitle">日日行动，日日有盈。<br>网页版 · 本地开发版<br><br>网页版与手机共用备份格式 16 / 数据结构 15，按记录合并。<br>桌面小组件以网页卡片呈现，手机端的强提醒仍由 Android 提供。</p>`)}</div></div>`;}
function datetime(at=Date.now()){const d=new Date(at);return `${D.dateString(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
const instant=v=>{const at=new Date(v).getTime();D.ensure(Number.isFinite(at),'日期时间无效');return at;};
