document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.dataset.action==='undo')return;e.preventDefault();act(b.dataset.action,b).catch(fail);});
document.addEventListener('change',e=>{if(e.target.dataset.select){if(e.target.checked)selected.add(e.target.dataset.select);else selected.delete(e.target.dataset.select);render();}if(e.target.dataset.check)mutate(d=>{const c=d.checklistItems.find(c=>c.id===e.target.dataset.check);c.done=e.target.checked;const t=d.todos.find(t=>t.id===c.todoId);t.revision++;},'').catch(fail);});
let dragging=null;
document.addEventListener('dragstart',e=>{const r=e.target.closest('[data-drag-table]');if(!r)return;dragging={table:r.dataset.dragTable,id:r.dataset.id};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',r.dataset.id);});
document.addEventListener('dragover',e=>{const r=e.target.closest('[data-drag-table]');if(r&&dragging?.table===r.dataset.dragTable){e.preventDefault();r.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>e.target.closest('[data-drag-table]')?.classList.remove('drag-over'));
document.addEventListener('drop',e=>{const r=e.target.closest('[data-drag-table]');if(!r||!dragging||r.dataset.dragTable!==dragging.table)return;e.preventDefault();r.classList.remove('drag-over');const {table,id}=dragging;dragging=null;if(id===r.dataset.id)return;mutate(d=>{const field=table==='notes'?'position':'sortOrder',rows=D.sorted(d[table]),picked=table==='todos'&&selected.has(id)?rows.filter(x=>selected.has(x.id)):rows.filter(x=>x.id===id),others=rows.filter(x=>!picked.includes(x)),target=others.findIndex(x=>x.id===r.dataset.id);D.ensure(target>=0,'不能拖到所选条目中');others.splice(target,0,...picked);others.forEach((x,i)=>{x[field]=i;});},'已调整顺序').catch(fail);});
window.addEventListener('beforeunload',e=>{if(editor?.pending||store?.state.dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)flushEditor().then(()=>store?.flush()).catch(fail);});
const notified=new Set();
setInterval(()=>{if(!store||!('Notification'in window)||Notification.permission!=='granted')return;const now=Date.now();for(const t of live('todos').filter(t=>!t.completedAt&&!t.repeatEndedAt&&t.planDate&&t.remindTime)){const at=new Date(`${t.planDate}T${t.remindTime}`).getTime()-(t.remindBefore??0)*60000,key=`${t.id}:${t.stateSeq}:${t.occurrenceCount}`;if(at<=now&&now-at<60000&&!notified.has(key)){notified.add(key);new Notification(t.title,{body:t.notes||'日盈 · 该做这件事了',tag:key,icon:'/icon.svg'});}}},15000);
api('/session').then(r=>start(r.value.user)).catch(e=>login(e.status===401?'':e.message));
